questionvariables.text:
/* Design: classify pattern (one dropdown per row, unique codes per row). [a, b, k1, k2]: f = a*x^2 + b, a a multiple of 3. Source: original. */
L: [[3,2,4,1],[6,-5,3,7],[9,4,2,5],[-3,7,6,2],[12,-1,5,3],[6,3,1,4],[-6,-4,7,2],[3,-8,2,6],[9,5,8,1],[-9,2,3,5]];
/* display order of the five candidate types (never a "yes" type first) and its inverse */
PM: [[5,3,2,4,1],[3,2,4,5,1],[5,1,4,3,2],[5,2,3,1,4],[4,2,3,1,5],[3,4,2,5,1],[4,5,2,3,1],[5,1,3,2,4],[3,2,1,4,5],[5,4,1,3,2]];
IP: [[5,3,2,4,1],[5,2,1,3,4],[2,5,4,3,1],[4,2,3,5,1],[4,2,3,1,5],[5,3,1,2,4],[5,3,4,1,2],[2,4,3,5,1],[3,2,1,4,5],[3,5,4,2,1]];
ix: 1+rand(10);
aa: L[ix][1]; bb: L[ix][2]; k1: L[ix][3]; k2: L[ix][4];
perm: PM[ix]; rw: IP[ix];
fx: aa*x^2+bb;
Fx: aa/3*x^3+bb*x;
/* types 1, 2 are integrals of f; 3 is f'(x); 4 forgot to divide; 5 left the constant b */
ty: [Fx+k1, Fx-k2, 2*aa*x, aa*x^3+bb*x, aa/3*x^3+bb];
cand: makelist(ty[perm[r]], r, 1, 5);
yes: makelist(is(perm[r] <= 2), r, 1, 5);
o1: [["i1", yes[1], "is an integral"], ["n1", not yes[1], "is not an integral"]];
o2: [["i2", yes[2], "is an integral"], ["n2", not yes[2], "is not an integral"]];
o3: [["i3", yes[3], "is an integral"], ["n3", not yes[3], "is not an integral"]];
o4: [["i4", yes[4], "is an integral"], ["n4", not yes[4], "is not an integral"]];
o5: [["i5", yes[5], "is an integral"], ["n5", not yes[5], "is not an integral"]];
/* correct and flipped codes per row, for the tests */
kcode: makelist(if yes[r] then sconcat("i", r) else sconcat("n", r), r, 1, 5);
flip: makelist(if yes[r] then sconcat("n", r) else sconcat("i", r), r, 1, 5);
dcand: makelist(diff(cand[r], x), r, 1, 5);

feedbackvariables.text:
A: [ans1, ans2, ans3, ans4, ans5];
mk: makelist(is(A[r] = kcode[r]), r, 1, 5);
ncorrect: sum(if mk[r] then 1 else 0, r, 1, 5);
said: makelist(is(A[rw[t]] = sconcat("i", rw[t])), t, 1, 5);
shiftno: (not said[1]) or (not said[2]);
derivyes: said[3];
nodivyes: said[4];
constyes: said[5];
